{
  "root_causes": [
    {
      "service": "ts-order-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-order-service' AND span_name IN ('SELECT ts.orders','SELECT Order','UPDATE ts.orders','INSERT ts.orders') GROUP BY 1,2 ORDER BY n DESC", "claim": "ts-order-service's SQL spans (SELECT ts.orders, SELECT Order) have p95 of about 4.6–5.6 seconds during the incident."},
        {"kind": "metric", "sql": "SELECT 'abn' p, time, count, sum, min, max FROM abnormal_metrics_histogram WHERE service_name='ts-order-service' AND metric='db.client.connections.use_time' UNION ALL SELECT 'norm', time, count, sum, min, max FROM normal_metrics_histogram WHERE service_name='ts-order-service' AND metric='db.client.connections.use_time' ORDER BY 1,2", "claim": "DB connection use_time rises from a max of about 200 ms to about 10 s per minute, with the pool still at 10 connections."},
        {"kind": "metric", "sql": "SELECT 'abn' p, time, count, sum, min, max FROM abnormal_metrics_histogram WHERE service_name='ts-order-service' AND metric='db.client.connections.wait_time' ORDER BY 2", "claim": "Connection wait_time grows to about 1.5 s per request in the abnormal window, against near-zero in normal."},
        {"kind": "metric", "sql": "SELECT 'abn' p, metric, round(avg(value),2) avg_v FROM abnormal_metrics_sum WHERE service_name IN ('mysql','ts-order-service') AND metric IN ('container.cpu.time') GROUP BY 1,2", "claim": "mysql and order-service container CPU stay near normal levels, so the database is not CPU-saturated."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-order-service", "to": "ts-seat-service",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name IN ('ts-order-service','ts-seat-service') AND span_name LIKE 'POST /api%' GROUP BY 1", "claim": "Seat-service POST p95 rises from about 50 ms to 2.7 s, in step with order-service p95 rising to 6 s."}]},
    {"from": "ts-seat-service", "to": "ts-travel-service",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name IN ('ts-seat-service','ts-travel-service') AND span_name LIKE 'POST /api%' GROUP BY 1", "claim": "Travel-service POST p95 rises from about 419 ms to 14 s, consistent with waiting on slow seat calls."}]},
    {"from": "ts-travel-service", "to": "ts-travel-plan-service",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name IN ('ts-travel-plan-service') AND span_name LIKE 'POST%' GROUP BY 1", "claim": "Travel-plan-service POST p95 rises from about 4.5 s to 23.9 s, inheriting travel-service latency."}]},
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard",
